#define R(p, a, r) mix(a * dot(p, a), p, cos(r)) + sin(r) * cross(p, a)
#define H(h) (cos((h) * 6.3 + vec3(0, 23, 21)) * 0.5 + 0.5)

void mainImage(out vec4 O, vec2 C) {
    O = vec4(0.0);
    vec3 p, r = iResolution;
    vec3 d = normalize(vec3((C * 2.0 - r.xy) / r.y, 1.0)); // Ray direction

    // Sample audio input for reactivity
    float audio = texture(iChannel0, vec2(0.01, C.y / r.y)).r;
    float audioIntensity = .250 + audio * 2.0;

    for (float i = 0.0, a, s, e, g = 0.0;
         ++i < 110.0;
         O.xyz += mix(vec3(1.0), H(g * 0.1), sin(0.8)) * audioIntensity / e / 8e3) {

        p = g * d;
        p.z += iTime * 6.5; // Z-axis motion
        a = 10.0;
        p = mod(p - a, a * 2.0) - a; // Recursive tiling
        s = 6.0;

        // Recursive fractal loop
        for (int j = 0; j++ < 8;) {
            p = 0.3 - abs(p); // Inversion for fractal effect

            // Axis permutation for symmetry
            p.x < p.z ? p = p.zyx : p;
            p.z < p.y ? p = p.xzy : p;

            // Recursive scaling and offset, modulated by audio
            s *= e = 1.4 + sin(iTime * 0.234 + audio * 0.5) * 0.1;
            p = abs(p) * e -
                vec3(
                    5.0 + cos(iTime * 0.3 + 0.5 * tan(iTime * 0.3)) * 3.0,
                    120.0,
                    8.0 + cos(iTime * 0.5 + audio * 0.3) * 5.0
                );
        }

        // Accumulate glow effects with audio modulation
        g += e = length(p.yz) / s;
        g += e = length(p.yx) / s; // Additional accumulation for dynamic lighting
    }

    // Add glow and color effects with audio-driven pulsations
    O.xyz = pow(O.xyz, vec3(0.9)); // Smooth glow
    O.xyz += 0.1 * sin(iTime * 2.0 + O.xyz * 10.0 + audio * 10.0); // Pulsations
    O.xyz *= 1.3 * (1.0 + audio * 0.5); // Amplify brightness based on audio

    O.w = 1.0; // Full opacity
}
